            'PHP'
        );
    }

    /**
     * Get the section when a path is given in a section
     *     ex. "session.save_path"
     */
    public function testGetSectionMultiple()
    {
        $path = 'session.save_path';
        $operation = new OperationStub('test');

        $this->assertEquals(
