function get_content_type_with_cache($file) {
    $fs = new Illuminate\Filesystem\Filesystem;
    $cacheKey = 'content_type_' . md5($file);
    $contentType = Cache::get($cacheKey);
    if ($contentType === null) {
        switch ($fs->extension($file)) {
        case 'jpeg': return 'image/jpeg';
        case 'jpg':  return 'image/jpeg';
        case 'jpe':  return 'image/jpeg';
        case 'gif':  return 'image/gif';
        case 'png':  return 'image/x-png';
        case 'css':  return 'text/css';
        case 'js':   return 'application/x-javascript';
        default:     
            if (class_exists('finfo')) {
                $finfo = new finfo(FILEINFO_MIME);
                $contentType = $finfo->file($file);
            } else {
                $contentType = 'application/octet-stream';
            }
        }
        Cache::put($cacheKey, $contentType, 60);
    }
    return $contentType;
}

