public function set( $key, $value, $group = 'default', $expiration = 0, $server_key = '', $byKey = false ) {
    if ( empty( $group ) ) {
        $group = 'default';
    }
    if ( $this->multisite && ! isset( $this->global_groups[ $group ] ) ) {
        $key = $this->blog_prefix . $key;
