function execute() {
	$documents = array();
	while ($this->queue_size() > 0) {
		$url = array_shift($this->url_queue);
		$doc = $this->download($url);
		if ($doc) {
			$documents[] = array('url' => $url, 'doc' => $doc);
		}
	}
	return $documents;
}

