	 *

	 * @param string $key the variable to parse

	 * @param string $curBlock the current parser-block being processed

	 * @return string parsed variable

	 */

	protected function parseVarKey($key, $curBlock)

	{

		if ($key === '') {

			return '$this->scope';

		}

		if (substr($key, 0, 1) === '.') {

			$key = 'dwoo'.$key;

		}

