			$global = strtoupper($m[1]);

			if ($global === 'COOKIES') {

				$global = 'COOKIE';

			}

			$key = '$_'.$global;

			foreach (explode('.', ltrim($m[2], '.')) as $part)

				$key .= '['.var_export($part, true).']';

