				$output = $key;

			} else {

				$output = '(isset('.$key.')?'.$key.':null)';

			}

		} elseif (preg_match('#dwoo\.const\.([a-z0-9_:]+)#i', $key, $m)) {

			return $this->parseConstKey($m[1], $curBlock);

