            $_POST['port'] = $_POST['port'];
            $query = "update admin set value='$_POST[port]' where variable='port'";
            DB::query($query);
            $_SESSION['msg'] = "Socket Updated.";
            redirectTo(SITE_URL . $_SESSION['url']);
        } else if (isset($_POST['judgenotice'])) {
