    public function __construct($gateway) {
        try {
            $this->gateway = $gateway;
            $this->skip_final_review = $this->gateway->get_option('skip_final_review', 'no');
            $this->billing_address = 'yes' === $this->gateway->get_option('billing_address', 'no');
