$lib_dir = dirname(dirname(__FILE__)) . '/lib/';
require_once $lib_dir . 'error_handler.php';
require_once $lib_dir . '../config/config.php';
if (defined('LOG_DIR')) {
	ini_set('error_log', LOG_DIR . 'selectivestatus.log');
