                        $tok = $p->next();
                        if ($tok === Tokenizer_CSSQuery::TOK_PIPE) {
                            $tok = $p->next();

                            if ($tok === Tokenizer_CSSQuery::TOK_ALL) {
                                $compare = 'namespace';
                            } elseif (($tag_name = $this->parse_getIdentifier()) !== false) {
