                    $conditions['tags'][] = array(
                        'tag' => $tag,
                        'match' => $match,
                        'operator' => $last_mode,
                        'compare' => $compare
                    );
                    switch ($tok) {
                        case Tokenizer_CSSQuery::TOK_COMMA:
                            $tok = $p->next_no_whitespace();
                            $last_mode = 'or';
                            continue 2;
                        case Tokenizer_CSSQuery::TOK_PLUS:
                            $tok = $p->next_no_whitespace();
                            $last_mode = 'and';
                            continue 2;
