        if (array_key_exists($key, $documentations)) {
          $this->checkCache($key);
          $this->processDocumentation($key, $query);
        }
      }
    } else {
      $this->checkCache($doc);
      $this->processDocumentation($doc, $query);
    }
    $this->render();
  }

