    # Extract passed vars
    extract($vars);

    # Start output buffer
    ob_start();

    # Ensure file exists
    if ( $path = getTemplatePath($file) ) {

        # Load template into buffer
        include $path;

        # Get buffer into variable
        $template = ob_get_contents();

