		if ( is_null( self::stability() ) ) {

			self::set_stability( new WPLib_Stability( WPLIB_STABILITY ) );

		}


		if ( ! defined( 'WPLIB_RUNMODE' ) ) {

			define( 'WPLIB_RUNMODE', is_null( self::runmode() )
				? WPLib_Runmode::__default
				: self::runmode()->get_value()
