			self::autoload_all_classes();

			self::cache_set( $cache_key, true );
		}

	}

	/**
	 * Return the list of classes declared after WPLib first loads.
	 * @return array
	 */
	static function site_classes() {

		if ( ! ( $site_classes = self::cache_get( $cache_key = 'site_classes' ) ) ) {

