	/**
	 * Return the templates directory path for the called class.
	 *
	 * @return string
	 */
	static function template_dir() {

		self::stability()->check_method( __METHOD__, WPLib_Stability::EXPERIMENTAL );

		return static::get_root_dir( 'templates' );

