	}

	/**
	 * Emits one or more HTTP headers to the output stream
	 *
	 * @param string|array $headers
	 */
	static function emit_headers( $headers ) {

		if ( ! is_array( $headers ) ) {
			$headers = array( $headers );
		}

		array_map( 'header', $headers );

	}

	/**
	 * @param string $filepath
