   * @var string

   */

  var $Host        = 'localhost';



  /**

   * Sets the default SMTP server port.

   * @var int

   */

  var $Port        = 25;



  /**

   * Sets the SMTP HELO of the message (Default is $Hostname).

   * @var string

   */

  var $Helo        = '';



  /**

   * Sets connection prefix.

   * Options are "", "ssl" or "tls"

