  var $cc              = array();

  var $bcc             = array();

  var $ReplyTo         = array();

  var $attachment      = array();

  var $CustomHeader    = array();

  var $message_type    = '';

  var $boundary        = array();

  var $language        = array();

  var $error_count     = 0;

  var $LE              = "\n";

  var $sign_cert_file  = "";

  var $sign_key_file   = "";

  var $sign_key_pass   = "";



