  /**

   * Changes every end of line from CR or LF to CRLF.

   * @access private

   * @return string

   */

  function FixEOL($str) {

    $str = str_replace("\r\n", "\n", $str);

    $str = str_replace("\r", "\n", $str);

    $str = str_replace("\n", $this->LE, $str);

    return $str;

