     * @var  array
     */
    protected $observers = [];

    /**
     * Request URL
     * @var  Net_URL2
     */
    protected $url;

    /**
     * Request method
     * @var  string
     */
    protected $method = self::METHOD_GET;

    /**
     * Authentication data
     * @var  array
     * @see  getAuth()
     */
    protected $auth;

    /**
     * Request headers
     * @var  array
     */
    protected $headers = [];

    /**
     * Configuration parameters
     * @var  array
     * @see  setConfig()
     */
    protected $config = [
        'adapter'           => 'HTTP_Request2_Adapter_Socket',
        'connect_timeout'   => 10,
        'timeout'           => 0,
        'use_brackets'      => true,
        'protocol_version'  => '1.1',
        'buffer_size'       => 16384,
        'store_body'        => true,
        'local_ip'          => null,

        'proxy_host'        => '',
        'proxy_port'        => '',
        'proxy_user'        => '',
        'proxy_password'    => '',
        'proxy_auth_scheme' => self::AUTH_BASIC,
        'proxy_type'        => 'http',

        'ssl_verify_peer'   => true,
        'ssl_verify_host'   => true,
        'ssl_cafile'        => null,
        'ssl_capath'        => null,
        'ssl_local_cert'    => null,
        'ssl_passphrase'    => null,

        'digest_compat_ie'  => false,

        'follow_redirects'  => false,
        'max_redirects'     => 5,
        'strict_redirects'  => false
    ];

