        } elseif ((($this->status['tag_name'][0] === '?') && ($this->doc[$this->pos] === '?'))
            || (($this->status['tag_name'][0] === '%') && ($this->doc[$this->pos] === '%'))
        ) {
            $this->status['self_close'] = true;
