public function select($query = '*', $index = false, $recursive = true, $check_self = false)
{
    $s = new $this->selectClass($this, $query, $check_self, $recursive);
    $res = $s->result;
    unset($s);
    if (is_array($res)) {
        if (($index === true) && (count($res) === 1)) {
            return $res[0];
        }
        if (is_int($index)) {
            if ($index < 0) {
                $index += count($res);
            }
            return ($index < count($res)) ? $res[$index] : null;
        }
    }
    return $res;
}

