	 * @param string $filter
	 * @param int $priority
	 */
	static function add_class_filter( $filter, $priority = 10 ) {

		$method = str_replace( [ '-', ':' , '.' ], '_', "_{$filter}" ) . ( 10 !== intval( $priority ) ? "_{$priority}" : '' );
		add_filter( $filter, array( get_called_class(), $method ), $priority, 99 );

	}

