	static function remove_class_action( $action, $priority = 10 ) {

		$method = str_replace( [ '-', ':' , '.' ], '_', "_{$action}" ) . ( 10 !== intval( $priority ) ? "_{$priority}" : '' );
		remove_action( $action, array( get_called_class(), $method ), $priority );

	}

