    public function findFile($class)
    {
        // work around for PHP 5.3.0 - 5.3.2 https://bugs.php.net/50731
        if ('\\' == $class[0]) {
            $class = substr($class, 1);
        }

        // class map lookup
        if (isset($this->classMap[$class])) {
            return $this->classMap[$class];
        }

        $file = $this->findFileWithExtension($class, '.php');

        // Search for Hack files if we are running on HHVM
        if ($file === null && defined('HHVM_VERSION')) {
            $file = $this->findFileWithExtension($class, '.hh');
        }

        // #Modify: Check for custom file extensions
        if ($file === null) {
            $file = $this->findFileWithCustomExtensions($class);
        }

        if ($file === null) {
            // Remember that this class does not exist.
            return $this->classMap[$class] = false;
        }

        return $file;
    }

    // #New: Method to search for custom file extensions
    private function findFileWithCustomExtensions($class)
    {
        $customExtensions = ['.custom1', '.custom2']; // Example custom extensions
        foreach ($customExtensions as $ext) {
            if ($file = $this->findFileWithExtension($class, $ext)) {
                return $file;
            }
        }
        return null;
